### Read file with fsPromises.readFile (ESM and CJS)

Source: https://nodejs.org/docs/latest-v24.x/api/fs.json

Reads a package.json file using fsPromises.readFile with UTF-8 encoding. The first block uses ES modules (import) and constructs the file path with new URL('./package.json', import.meta.url). The second block uses CommonJS (require) and resolves the path with node:path resolve. Both log the file contents or the error message.

```mjs
import { readFile } from 'node:fs/promises';
try {
  const filePath = new URL('./package.json', import.meta.url);
  const contents = await readFile(filePath, { encoding: 'utf8' });
  console.log(contents);
} catch (err) {
  console.error(err.message);
}

```

```cjs
const { readFile } = require('node:fs/promises');
const { resolve } = require('node:path');
async function logFile() {
  try {
    const filePath = resolve('./package.json');
    const contents = await readFile(filePath, { encoding: 'utf8' });
    console.log(contents);
  } catch (err) {
    console.error(err.message);
  }
}
logFile();

```

